//! Area ping uses USVString at the reflected property boundary.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><area id=area ping=initial><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://area-ping.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn area_ping_canonical_descriptors(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),a=Object.getOwnPropertyDescriptor(HTMLAreaElement.prototype,'ping');if(!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get ping'||a.set.name!=='set ping'||x.ping!=='initial'||Object.hasOwn(x,'ping'))throw 'canonical ping accessor';"#);}
#[test]
fn area_ping_native_usv_setter_and_raw_attr_getter(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),a=x.getAttributeNode('ping');x.ping='A\ud800Z';if(x.ping!=='A\ufffdZ'||a.value!=='A\ufffdZ'||x.getAttributeNode('ping')!==a)throw 'USV setter';a.value='R\udfffZ';if(a.value!=='R\udfffZ'||x.ping!=='R\ufffdZ')throw 'USV getter preserves raw Attr';x.removeAttribute('ping');if(x.ping!==''||a.ownerElement!==null||a.value!=='R\udfffZ')throw 'removed ping';"#);}
#[test]
fn area_ping_inert_once_conversion_namespace_clone(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','t:area'),calls=0;x.ping={toString:function(){calls++;x.setAttribute('ping','author');return 'R\udfffZ';}};if(calls!==1||x.ping!=='R\ufffdZ'||x.getAttribute('ping')!==x.ping)throw 'once USV conversion';x.setAttributeNS('urn:foreign','ping','foreign');x.setAttributeNS(null,'PING','upper');var clone=x.cloneNode(false);if(x.ping!=='R\ufffdZ'||clone.ping!==x.ping)throw 'exact namespace';clone.ping='independent';if(x.ping!=='R\ufffdZ')throw 'independent clone';"#);}
#[test]
fn area_ping_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),old=x.getAttributeNode('ping'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.ping={toString:function(){calls++;x.removeAttribute('ping');x.setAttribute('ping','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('ping'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='initial'||current.value!=='A\ufffdZ'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.ping={toString:function(){x.setAttribute('ping','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.ping!=='author effect'||records.length!==1||records[0].oldValue!=='A\ufffdZ')throw 'abrupt conversion preserves author effect';caught=false;try{x.ping=Symbol('area');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.ping!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.ping=value;if(x.ping!==String(value))throw 'ordinary DOMString conversion';}if(x.textContent!=='')throw 'metadata leaves displayed text';"#);
}
#[test]
fn area_ping_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),C=HTMLAreaElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'ping'),calls=0;for(var bad of [{},Object.create(P),document.body,document.createElementNS('urn:foreign','area'),new Document().createElementNS('http://www.w3.org/1999/xhtml','AREA')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'ping',{value:'author',writable:true,configurable:true});if(x.ping!=='author'||a.get.call(x)!=='initial')throw 'canonical authority';a.set.call(x,'canonical');if(x.ping!=='author'||x.getAttribute('ping')!=='canonical')throw 'borrowed real setter';delete x.ping;if(x.ping!=='canonical'||Object.hasOwn(x,'ping'))throw 'restored inherited reflection';delete window.HTMLAreaElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}
#[test]
fn area_ping_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('area'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLAreaElement,a=Object.getOwnPropertyDescriptor(C.prototype,'ping'),calls=0;if(C===HTMLAreaElement||a.get.call(x)!=='initial')throw 'captured area accessor';"#);p.set_location(&crate::navigation::address("https://other-time.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://area-ping.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'area origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.
#[test]
fn area_ping_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.ping='Long canonical \ud800 DateTime replacement';",r"x.setAttribute('ping','Long canonical \ud800 DateTime replacement');",r"attr.value='Long canonical \ud800 DateTime replacement';",r"attr.nodeValue='Long canonical \ud800 DateTime replacement';",r"attr.textContent='Long canonical \ud800 DateTime replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.setAttribute('ping','initial');"}else{"var x=document.getElementById('area');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('ping'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("alt writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='initial'||x.ping!=='initial'||watch.takeRecords().length)throw 'atomic alt writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.ping!=='Long canonical \ufffd DateTime replacement'||records.length!==1||records[0].oldValue!=='initial'||records[0].attributeName!=='ping'||x.getAttributeNode('ping')!==attr)throw 'fresh alt writer recovery';");
 }}}
}
#[test]
fn area_ping_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var time=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');time.ping='A\ud800Z';");let Value::Host(object)=p.runtime.execute("time;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert time handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('area').ping='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("area")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_ping_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_ping_get(object).is_ok());}}
}


#[test]
fn area_ping_native_and_inert_exact_attached_aliases_and_namespace(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.setAttribute('ping','initial');"}else{"var x=document.getElementById('area');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('ping');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.ping!=='R\ufffd'+writer||x.getAttributeNode('ping')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','ping','foreign');x.setAttributeNS(null,'PING','upper');if(x.ping!=='R\ufffdtextContent'||x.getAttributeNodeNS(null,'ping')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'ping','alternative');if(x.ping!=='alternative'||a.value!==x.ping)throw 'null namespace writer';x.removeAttributeNS(null,'ping');if(x.ping!==''||a.ownerElement!==null||a.value!=='alternative')throw 'removed actual alt';"#);}
}
#[test]
fn area_ping_native_copy_import_and_neighbor_attribute_guards_remain_atomic(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('area'),source=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');source.ping='actual';var neighbor=document.getElementById('neighbor');");
 for code in ["x.cloneNode(false);","document.importNode(source,false);",r"neighbor.setAttribute('ping','A\ud800Z');"]{let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("not implemented")||e.contains("Import supports ordinary HTML containers and inert data nodes.")||e.contains("Unpaired attribute"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.ping!=='actual'||x.ping!=='initial'||neighbor.value!=='seed'||neighbor.hasAttribute('ping'))throw 'preserved native and neighbor guards';");}
}


#[test]
fn area_ping_scalar_pairs_and_raw_getter_do_not_rewrite_attributes(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.setAttribute('ping','initial');"}else{"var x=document.getElementById('area');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('ping'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.ping='A\ud83d\ude00Z';if(x.ping!=='A\ud83d\ude00Z'||a.value!==x.ping||x.ping.length!==4)throw 'valid pair preserved';watch.takeRecords();a.value='\ud800A\udfff\ud83d\ude00';var records=watch.takeRecords();if(records.length!==1||x.ping!=='\ufffdA\ufffd\ud83d\ude00'||a.value!=='\ud800A\udfff\ud83d\ude00'||watch.takeRecords().length||x.getAttributeNode('ping')!==a)throw 'scalar getter leaves raw Attr and records unchanged';"#);}
}

#[test]
fn area_ping_raw_getter_projection_budget_is_atomic_and_recovers(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{r"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','area');x.setAttribute('ping','\ud800');"}else{r"var x=document.getElementById('area');x.setAttribute('ping','\ud800');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('ping'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");let Value::Host(object)=p.runtime.execute("x;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("area handle")};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let strings=p.state.limits.host.string_bytes;let retained=p.state.retained_limit;p.begin_job();match mode{0=>p.state.limits.host.string_bytes=2,1=>p.state.copy_work=2,2=>p.state.host_work=0,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.area_ping_get(object);if mode==4{let Value::String(value)=result.unwrap()else{panic!("USV result")};assert_eq!(value,"\u{fffd}");}else{let error=result.unwrap_err();assert!(error.contains("allowance")||error.contains("work")||error.contains("bound")||error.contains("time"),"{error}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.limits.host.string_bytes=strings;p.state.retained_limit=retained;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,r"if(x.ping!=='\ufffd'||attr.value!=='\ud800'||watch.takeRecords().length||x.getAttributeNode('ping')!==attr)throw 'raw USV read recovery';");}}
}
